declare(strict_types=1); if(session_status()===PHP_SESSION_NONE){session_name('PENDENZ_SESSID');session_start();}
require_once __DIR__.'/../../config.php';require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../includes/authz.php';require_once __DIR__.'/bootstrap.php';require_once __DIR__.'/lib.php';if(file_exists(__DIR__.'/../../vendor/autoload.php')) require_once __DIR__.'/../../vendor/autoload.php';require_login(); if(!in_array($_SESSION['rolle']??'', ['admin','superadmin'],true)){http_response_code(403);exit;}
nk_bootstrap($mysqli);$pid=(int)($_GET['projekt_id']??0);$year=(int)($_GET['jahr']??date('Y'));$format=$_GET['format']??'csv';$rows=nk_load_bookings($mysqli,$pid,$year);$units=[];$st=$mysqli->prepare('SELECT w.id AS wohnung_id,COALESCE(w.flaeche,0) area FROM wohnungen w JOIN objekte o ON o.id=w.objekt_id WHERE o.projekt_id=?');if($st){$st->bind_param('i',$pid);$st->execute();$units=$st->get_result()->fetch_all(MYSQLI_ASSOC);$st->close();}foreach($units as &$u){$u['units']=1;$u['persons']=1;}unset($u);$r=nk_calculate_statement($rows,$units,($year%4===0?366:365));
if($format==='csv'){header('Content-Type:text/csv; charset=utf-8');header('Content-Disposition:attachment; filename="nebenkosten-'.$pid.'-'.$year.'.csv"');$o=fopen('php://output','w');fputcsv($o,['Wohnung','Umlageanteil CHF','Akonto CHF','Saldo CHF'],';');foreach($r['by_unit'] as $id=>$v)fputcsv($o,[$id,number_format($v,2,'.',''),'',number_format($v,2,'.','')],';');fputcsv($o,[],';');fputcsv($o,['Eigentümer steuerlich effektiv CHF',number_format($r['owner_effective'],2,'.','')],';');fputcsv($o,['Pauschalvergleich CHF',number_format($r['owner_flat'],2,'.','')],';');fclose($o);exit;}
$html='<html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans;font-size:11px}h1{color:#0f766e}table{border-collapse:collapse;width:100%}th,td{border-bottom:1px solid #ccc;padding:5px;text-align:left}.num{text-align:right}</style></head><body><h1>Nebenkostenabrechnung '.$year.'</h1><p>Liegenschaft #'.$pid.'</p><h2>Mieterübersicht</h2><table><tr><th>Wohnung</th><th class="num">Umlage CHF</th><th class="num">Saldo CHF</th></tr>';foreach($r['by_unit'] as $id=>$v)$html.='<tr><td>'.htmlspecialchars((string)$id).'</td><td class="num">'.number_format($v,2,'.',"'").'</td><td class="num">'.number_format($v,2,'.',"'").'</td></tr>';$html.='</table><h2>Eigentümer-/Steuerübersicht</h2><p>Effektiv: CHF '.number_format($r['owner_effective'],2,'.',"'").'<br>Pauschalvergleich: CHF '.number_format($r['owner_flat'],2,'.',"'").'</p><p>Hinweis: Kantonale und individuelle steuerliche Prüfung erforderlich.</p></body></html>';
if(class_exists('Dompdf\\Dompdf')){ $opt=new Dompdf\Options();$opt->set('isRemoteEnabled',false);$pdf=new Dompdf\Dompdf($opt);$pdf->loadHtml($html);$pdf->setPaper('A4');$pdf->render();$pdf->stream('nebenkosten-'.$pid.'-'.$year.'.pdf',['Attachment'=>true]); } else {header('Content-Type:text/html; charset=utf-8');echo $html;}
